import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"基本概念","description":"","frontmatter":{"title":"基本概念"},"headers":[],"relativePath":"start/concepts.md","filePath":"start/concepts.md","lastUpdated":1787949005000}'),i={name:"start/concepts.md"};function l(s,a,n,c,h,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><p>熠智 AI 里有几个核心概念。花五分钟弄清它们的关系，后面的配置会顺很多。</p><h2 id="整体是怎么工作的" tabindex="-1">整体是怎么工作的 <a class="header-anchor" href="#整体是怎么工作的" aria-label="Permalink to &quot;整体是怎么工作的&quot;">​</a></h2><p>熠智 AI 的接待在<strong>你的电脑上</strong>运行。桌面客户端会打开各平台的客服窗口（比如千牛、拼多多商家版网页），读取顾客消息，按你配置的 AI 方案生成回复并发送。</p><p>这意味着：</p><ul><li>接待期间电脑要开机、客户端要保持运行。</li><li>你的店铺账号在自己电脑上登录，不需要把密码交给别人。</li><li>关掉客户端或电脑，AI 就停止接待。</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>熠智 AI 不是云端托管服务。如果你需要下班后也有人接待，可以配置<a href="/aicare-docs/solution/general#夜间服务模式">夜间服务模式</a>，或安排电脑不关机。</p></div><h2 id="店铺" tabindex="-1">店铺 <a class="header-anchor" href="#店铺" aria-label="Permalink to &quot;店铺&quot;">​</a></h2><p>「店铺」是客户端里的基本管理单位。一个店铺下可以挂多个平台客服账号，这些账号<strong>共用同一套 AI 方案和转人工设置</strong>。</p><p>举例：你的淘宝店有 3 个千牛客服号，把它们挂在同一个店铺下，AI 用同一套话术接待，转人工时也在这 3 个号之间分配。</p><p>详见<a href="/aicare-docs/client/shops">接入店铺和客服账号</a>。</p><h2 id="客服账号" tabindex="-1">客服账号 <a class="header-anchor" href="#客服账号" aria-label="Permalink to &quot;客服账号&quot;">​</a></h2><p>挂在店铺下的具体平台账号，比如某个千牛子账号、某个拼多多客服号。每个客服账号可以单独开关 AI 接待。</p><h2 id="ai-方案" tabindex="-1">AI 方案 <a class="header-anchor" href="#ai-方案" aria-label="Permalink to &quot;AI 方案&quot;">​</a></h2><p>AI 方案决定 AI「怎么回复」。一个方案里包含：</p><ul><li><strong>AI 设置</strong>：角色设定、智能程度、可用工具。</li><li><strong>知识库绑定</strong>：AI 回答时参考哪些资料。</li><li><strong>关键词回复</strong>：命中关键词时用固定话术，优先级高于 AI。</li><li><strong>通用配置</strong>：消息间隔、夜间模式、新客欢迎语等。</li></ul><p>一个方案可以给多个店铺用；换方案只需要在店铺设置里重新选择。详见<a href="/aicare-docs/solution/editor">方案编辑器</a>。</p><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><p>知识库是 AI 回答的依据，里面放问答、文档和商品资料。知识库独立于方案存在——建好一个知识库后，可以绑定到多个方案上。详见<a href="/aicare-docs/knowledge/basics">知识库是什么</a>。</p><h2 id="点数" tabindex="-1">点数 <a class="header-anchor" href="#点数" aria-label="Permalink to &quot;点数&quot;">​</a></h2><p>点数是使用量的计量单位。AI 回复、商品学习等动作会消耗客服接待点数；套餐按周期发放，不够可以买加油包。运营助手使用另一份按自然月计算的额度，普通加油包不包含这份额度。详见<a href="/aicare-docs/billing/points">点数怎么计算</a>。</p><h2 id="桌面客户端和网页工作台" tabindex="-1">桌面客户端和网页工作台 <a class="header-anchor" href="#桌面客户端和网页工作台" aria-label="Permalink to &quot;桌面客户端和网页工作台&quot;">​</a></h2><ul><li><strong>桌面客户端</strong>：日常接待的主战场。接入店铺、开关 AI、查看实时会话都在这里。</li><li><strong>网页工作台</strong>：在浏览器里登录官网进入，适合远程查看聊天记录、改方案、看账单。接待本身不在网页端运行。</li></ul><p>详见<a href="/aicare-docs/client/overview">客户端总览</a>和<a href="/aicare-docs/workspace/overview">工作台总览</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/aicare-docs/start/register">注册账号</a></li><li><a href="/aicare-docs/start/download">下载安装客户端</a></li></ul>',26)])])}const f=e(i,[["render",l]]);export{u as __pageData,f as default};
